import{_ as e,o as n,c as p,a2 as s}from"./chunks/framework.BXzK3EA4.js";const i="/assets/d072a5f441c77950.ChUlspLc.png",o="/assets/61890193282c5b73.Myr22-5y.png",a="data:image/png;base64,",r="/assets/1307497af14e0233.BwuTnARw.png",c="/assets/53f68973223c24ac.Cg3owdaF.png",l="/assets/16312710f0f53574.CsFJxJMi.png",A="/assets/e70cc480cced8646.BwlO3X6P.png",T=JSON.parse('{"title":"如何使用Putty工具远程linux系统","description":"","frontmatter":{"title":"如何使用Putty工具远程linux系统"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/remote-login-with-putty.md","filePath":"ops-knowledge-base/operating-system/linux/remote-login-with-putty.md","lastUpdated":1788259091000}'),m={name:"ops-knowledge-base/operating-system/linux/remote-login-with-putty.md"};function d(u,t,g,w,P,D){return n(),p("div",null,[...t[0]||(t[0]=[s('<p>Putty软件简介</p><p>PuTTY是一个Telnet、SSH、rlogin、纯TCP以及串行接口连接软件。较早的版本仅支持Windows平台，在最近的版本中开始支持各类Unix平台，并打算移植至Mac OS X上。除了官方版本外，有许多第三方的团体或个人将PuTTY移植到其他平台上，像是以Symbian为基础的移动电话。PuTTY为一开放源代码软件，主要由Simon Tatham维护，使用MIT licence授权。随着Linux在服务器端应用的普及，Linux系统管理越来越依赖于远程。在各种远程登录工具中，Putty是出色的工具之一。Putty是一个免费的、Windows x86平台下的Telnet、SSH和rlogin客户端，但是功能丝毫不逊色于商业的Telnet类工具。</p><p>下载链接：<a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/" target="_blank" rel="noreferrer">PuTTY：一个免费的SSH和Telnet客户端 (greenend.org.uk)</a></p><p><img src="'+i+'" alt=""></p><p>点击上图红色箭头下载，跳转到下图界面，选择适合自己系统的链接下载。</p><p><img src="'+o+'" alt=""></p><p>点击上图红色箭头下载，下载安装完成后如下图图标所示：</p><p><img src="'+a+'" alt=""></p><p>1.连接步骤如下：</p><ul><li><p>输入实例IP地址</p></li><li><p>实例远程端口号，Linux默认端口号为22，下图为随机设置的端口号</p></li><li><p>选择连接类型SSH</p></li><li><p>打开</p></li></ul><p><img src="'+r+'" alt=""></p><ul><li>点击Accept</li></ul><p><img src="'+c+'" alt=""></p><p>2.输入用户名和密码，密码是不显示的可以复制粘贴</p><p><img src="'+l+'" alt=""></p><p>3.如下图所示成功远程实例</p><p><img src="'+A+'" alt=""></p>',17)])])}const v=e(m,[["render",d]]);export{T as __pageData,v as default};
